import {renderFishContracts} from './fish-contract-view.js';
import {FEATURES} from './features.js';import {t,getLocale} from './locales.js';import {fishSaleValue} from './fish-sales.js';
/** @param {import('./engine.js').State} state @param {(type:import('./engine.js').CommandType,extra?:Partial<import('./engine.js').Command>)=>void} send @param {HTMLElement} host */
export function renderFishMarket(state,send,host){const g=state.fish;if(!FEATURES.fish||!g?.visited)return;const section=document.createElement('section');section.id='fish-market';section.setAttribute('aria-labelledby','fish-market-title');const title=document.createElement('h3');title.id='fish-market-title';title.textContent=t('fishHarvestLots');section.append(title);for(const lot of g.lots){const row=document.createElement('div');row.className='market-lot';row.dataset.fishLot=lot.id;const text=document.createElement('span');text.textContent=(g.ponds.length>1?t('fishPondLabel')+' '+lot.pondId+' · ':'')+lot.count+' '+t('fishCount')+' · '+(lot.massG/1000).toLocaleString(getLocale())+' kg · '+t('grade')+' '+lot.grade;const button=document.createElement('button');button.type='button';button.className='action-button primary';button.dataset.sellFish=lot.id;button.textContent=t('sell')+' · +'+fishSaleValue(lot)+' '+t('coins');button.addEventListener('click',event=>{if(event.detail>1)return;button.disabled=true;Promise.resolve(send('fish.sell',{fishPond:lot.pondId,fishLot:lot.id})).finally(()=>{if(button.isConnected)button.disabled=false;});});row.append(text,button);section.append(row);}if(!g.lots.length){const empty=document.createElement('p');empty.textContent=t('fishNoHarvestLots');section.append(empty);}renderFishContracts(state,send,section);host.append(section);}
